export interface BoxDimensions {
  length: number; // mm
  width: number; // mm
  height: number; // mm
}

export interface PaperSpecs {
  gsm: number; // g/m2
  pricePerKg: number; // THB
}

export interface ProductionSpecs {
  quantity: number;
  markupPercent: number;
  fixedCost: number; // Startup cost (Printing plates)
  dieCutPlateCost: number; // Additional fixed cost (Die-cut block)
  printCostPerUnit: number; // Printing & Die-cutting labor per unit
  // Post-press
  hasGluing: boolean;
  gluingCostPerUnit: number;
  hasLamination: boolean;
  laminationCostPerUnit: number;
}

export interface CostBreakdown {
  paperCostPerUnit: number;
  productionCostPerUnit: number;
  totalCostPerUnit: number;
  sellingPricePerUnit: number;
  totalOrderValue: number;
  totalProfit: number;
  paperWeightPerBox: number; // grams
  estimatedSheetSize: {
    w: number;
    h: number;
  };
}

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
  timestamp: number;
}
